@page "/notepad"
@rendermode InteractiveServer
@inject IJSRuntime JS
@implements IAsyncDisposable

<PageTitle>Notepad</PageTitle>

<h1>Notepad</h1>

<div class="notepad-container">
    <textarea class="form-control notepad-textarea"
              @bind="content"
              @bind:event="oninput"
              placeholder="Type your notes here…"></textarea>

    <div class="notepad-toolbar">
        <div class="notepad-status">
            @if (lastSavedAt is not null)
            {
                <span>Last saved at @lastSavedAt.Value.ToString("HH:mm:ss")</span>
            }
        </div>
        <div class="notepad-actions">
            <button class="btn btn-outline-danger" @onclick="ClearAsync">Clear</button>
            <button class="btn btn-primary" @onclick="SaveNowAsync">Save now</button>
        </div>
    </div>
</div>

@code {
    private NotepadInterop? interop;
    private string content = "";
    private string savedContent = "";
    private DateTime? lastSavedAt;
    private System.Threading.Timer? autoSaveTimer;

    protected override void OnInitialized()
    {
        autoSaveTimer = new System.Threading.Timer(
            _ => _ = InvokeAsync(AutoSaveAsync),
            null,
            TimeSpan.FromSeconds(30),
            TimeSpan.FromSeconds(30));
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            interop = new NotepadInterop(JS);
            content = await interop.LoadContentAsync();
            savedContent = content;
            StateHasChanged();
        }
    }

    private bool HasUnsavedChanges => content != savedContent;

    private async Task SaveNowAsync()
    {
        if (interop is null) return;
        await interop.SaveContentAsync(content);
        savedContent = content;
        lastSavedAt = DateTime.Now;
        await interop.DisableLeaveGuardAsync();
    }

    private async Task AutoSaveAsync()
    {
        if (interop is null || !HasUnsavedChanges) return;
        await SaveNowAsync();
        StateHasChanged();
    }

    private async Task ClearAsync()
    {
        if (interop is null) return;
        content = "";
        savedContent = "";
        lastSavedAt = null;
        await interop.ClearContentAsync();
        await interop.DisableLeaveGuardAsync();
    }

    protected override async Task OnAfterRenderAsync()
    {
        // Keep leave guard in sync with unsaved-changes state after every render.
        if (interop is null) return;
        if (HasUnsavedChanges)
            await interop.EnableLeaveGuardAsync();
        else
            await interop.DisableLeaveGuardAsync();
    }

    public async ValueTask DisposeAsync()
    {
        if (autoSaveTimer is not null)
            await autoSaveTimer.DisposeAsync();

        if (interop is not null)
            await interop.DisposeAsync();
    }
}

.notepad-container {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
    max-width: 800px;
}

.notepad-textarea {
    min-height: 300px;
    resize: vertical;
    font-family: inherit;
}

.notepad-toolbar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 0.5rem;
}

.notepad-status {
    color: #6c757d;
    font-size: 0.875rem;
}

.notepad-actions {
    display: flex;
    gap: 0.5rem;
}

